const rows = $('Collect chat').item.json.rows || '[]';
const factCtx = $('Collect chat').item.json.fact_contexts || 'family';
const noteCtx = $('Collect chat').item.json.note_contexts || 'family';
// rationale erscheint auf der Lern-Karte des Owners -> in seiner Sprache (Textkatalog Phase C); value bleibt verbatim
let ui = {};
try { ui = JSON.parse($('Collect chat').item.json.ui || '{}'); } catch (e) { ui = {}; }
const lang = ui.language_label || 'en';
const instr = [
  'You extract DURABLE, long-term-relevant facts and insights from a household\'s recent chat with their personal assistants (finances, career, estate planning and more), to build a private long-term memory.',
  'Input: a JSON array of recent USER messages, each { agent_name, source_id, content }.',
  'Emit ONE candidate per genuinely durable item worth remembering long-term. Two kinds:',
  '- target_kind "fact": a structured household fact for a known slot. context_name MUST be one of: ' + factCtx + ' ("family" = person identity / household; any other = the per-person facts profile of an installed package). Provide person_slug (the lowercase person id), field (e.g. birth_date, last_name, citizenship, language) and value = the RAW value the user stated, verbatim in the language the user used (never translated). Exception: field language = the code (de|en|ko). NEVER a computed/derived value (no ages, calendar years, projections, nominal amounts) - only the raw fact.',
  '- target_kind "note": a richer insight that fits no fixed slot (plans, preferences, life events, intentions). context_name MUST be one of: ' + noteCtx + '. value = a short note (one sentence) in the language of the source message. For notes NEVER include computed or derived numbers.',
  'For EACH candidate copy agent_name and source_id VERBATIM from the source message it came from (so the same item is never relearned).',
  'Only emit clearly durable items - skip small talk, questions, transient details, and anything already obvious. If nothing is worth remembering, return [].',
  'Return ONLY a JSON array, no prose and no markdown code fences:',
  '[{ "target_kind": "fact|note", "context_name": "...", "person_slug": "...", "field": "...", "value": "...", "agent_name": "...", "source_id": 123, "rationale": "..." }]',
  'rationale = a short phrase in the language ' + lang + ': what you learned and from which message.'
].join('\n');
return [{ json: { prompt: instr + '\n\nRecent user messages (JSON):\n' + rows } }];

let raw = ($input.first().json && $input.first().json.text) || '';
raw = String(raw).replace(/^\s*```(?:json)?/i, '').replace(/```\s*$/i, '').trim();
let candidates = [];
try { const p = JSON.parse(raw); if (Array.isArray(p)) candidates = p; } catch (e) { candidates = []; }
let watermarks = [];
try { watermarks = JSON.parse($('Collect chat').item.json.watermarks || '[]'); } catch (e) { watermarks = []; }
return [{ json: { candidates: candidates, watermarks: watermarks } }];

function uiRender(B, LANGS) {
  B = B || {};
  LANGS = LANGS || {};
  const T = B.t || {};
  const loc = B.locale || 'en-GB';
  // fn_ui_texts liefert fuer einen fehlenden Key den Key selbst -> das zaehlt hier als "nicht vorhanden".
  const has = (k) => Object.prototype.hasOwnProperty.call(T, k) && T[k] !== k;
  const t = (k) => (has(k) ? T[k] : String(k));
  const empty = has('core.fmt.empty') ? T['core.fmt.empty'] : '—';
  const isEmpty = (v) => v === null || v === undefined || v === '';
  // Platzhalter in EINEM Durchlauf: einfache Werte unveraendert (auch '' fuer optionale Zusaetze wie die Einheit),
  // nur typisierte Werte ({kind: money|date|enum|...}) laufen durch val(); null/undefined -> ''. Ein FEHLENDER
  // Parameter zaehlt wie undefined: n8n verwirft undefined-Felder beim Speichern des Summary-Objekts, sonst stuende
  // Rohtext wie "{isin}" auf der Karte (Owner 2026-10-22). Vertippte Parameter-Namen faengt der Build
  // (Assert-HitlTplParams in New-HitlLine/New-HitlNote/New-HitlSummary).
  function fill(txt, params) {
    return String(txt).replace(/\{(\w+)\}/g, (m, n) => {
      if (!params || !Object.prototype.hasOwnProperty.call(params, n)) return '';
      const p = params[n];
      if (p === null || p === undefined) return '';
      return (typeof p === 'object') ? val(p) : String(p);
    });
  }
  // sign = true (core.fn_ui_money p_sign): '+' vor positive Betraege (Gewinn seit Kauf); negative tragen ihr Minus ohnehin.
  function money(v, c, sign) {
    if (isEmpty(v)) return empty;
    const n = Number(v);
    if (!isFinite(n)) return String(v);
    const plus = (sign === true && n > 0) ? '+' : '';
    // Ohne gueltigen Waehrungscode KEIN stilles EUR (ein USD-Betrag sahe sonst wie Euro aus): Zahl + Rohcode.
    if (!(typeof c === 'string' && /^[A-Za-z]{3}$/.test(c))) return plus + num(v, 2) + (isEmpty(c) ? '' : ' ' + String(c));
    const cur = c.toUpperCase();
    try { return plus + Number(n).toLocaleString(loc,{style:'currency',currency:(/^[A-Za-z]{3}$/.test(cur)?cur:'EUR'),currencyDisplay:'narrowSymbol'}); } catch (e) { return plus + String(v) + ' ' + cur; }
  }
  // B.date_short = {from, to} (nur die Mini-App, core.fn_app_screen): ein ISO-Datum im Fenster [from, to) ohne Jahr
  // (String-Vergleich, die App rechnet kein Datum); Chat/HITL/Cron setzen es nie -> dort immer mit Jahr.
  const DS = (B.date_short && typeof B.date_short.from === 'string' && typeof B.date_short.to === 'string') ? B.date_short : null;
  function date(v) {
    if (isEmpty(v)) return empty;
    const m = DS ? /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(v)) : null;
    if (m && String(v) >= DS.from && String(v) < DS.to) {
      try { return new Date(Date.UTC(+m[1], +m[2] - 1, +m[3])).toLocaleDateString(loc, { timeZone: 'UTC', month: '2-digit', day: '2-digit' }); }
      catch (e) { /* weiter mit Jahr */ }
    }
    try { return ((m) => m ? new Date(Date.UTC(+m[1], +m[2] - 1, +m[3])).toLocaleDateString(loc, {timeZone:'UTC', year:'numeric', month:'2-digit', day:'2-digit'}) : String(v))(/^(\d{4})-(\d{2})-(\d{2})/.exec(String(v))); } catch (e) { return String(v); }
  }
  // Nachkommastellen, die der Wert selbst traegt (ohne Null-Schwanz der DB, z. B. numeric(18,8) "10.00000000" -> 0).
  function decimals(v) {
    const s = String(v).trim();
    const e = s.match(/^-?\d+(?:\.(\d+))?e-(\d+)$/i);
    if (e) return Math.min(20, (e[1] || '').length + Number(e[2]));
    const m = s.match(/\.(\d+)$/);
    return m ? Math.min(20, m[1].replace(/0+$/, '').length) : 0;
  }
  // digits < 0 = so viele Stellen wie der Wert hat (Stueckzahlen: Krypto bis 8 Stellen, nie gerundet).
  function num(v, digits, sign) {
    if (isEmpty(v)) return empty;
    const n = Number(v);
    if (!isFinite(n)) return String(v);
    const d = (Number(digits) < 0) ? decimals(v) : Math.max(0, Math.min(6, Number(digits) || 0));
    try { return n.toLocaleString(loc, { minimumFractionDigits: d, maximumFractionDigits: d, signDisplay: sign ? 'exceptZero' : 'auto' }); }
    catch (e) { return String(v); }
  }
  function val(x) {
    if (isEmpty(x)) return empty;
    if (typeof x !== 'object') return String(x);
    if (Array.isArray(x)) return x.length ? x.map(val).join(', ') : empty;
    const v = x.value;
    switch (x.kind) {
      case 'money': return money(v, x.currency, x.sign);
      case 'date': return date(v);
      case 'number': return num(v, x.digits, x.sign);
      case 'enum': {
        if (isEmpty(v)) return empty;
        const k = String(x.enum) + '.' + String(v).toLowerCase().replace(/[^a-z0-9_]+/g, '_');
        return has(k) ? T[k] : String(v);
      }
      case 'bool': return (v === true || v === 'true') ? t('core.fmt.yes')
        : ((v === false || v === 'false') ? t('core.fmt.no') : empty);
      case 'language': return isEmpty(v) ? empty : (LANGS[v] || String(v));
      case 'key': return isEmpty(v) ? empty : (has(v) ? T[v] : (x.fallback || String(v)));
      case 'tpl': return isEmpty(v) ? empty : fill(t(v), x.params);
      case 'removed': return t('core.fmt.removed');
      case 'list': return (Array.isArray(v) && v.length) ? v.map(val).join(', ') : empty;
      default: return isEmpty(v) ? empty : (Array.isArray(v) ? v.join(', ') : String(v));
    }
  }
  function msg(parts) {
    return (Array.isArray(parts) ? parts : [parts]).filter((p) => !isEmpty(p)).map(val).join(' ');
  }
  function lines(ls) {
    return (Array.isArray(ls) ? ls : []).map((l) => (l === null || l === undefined) ? ''
      : (Array.isArray(l) ? msg(l) : val(l))).join('\n');
  }
  return { T, loc, has, t, empty, isEmpty, fill, money, date, num, val, msg, lines };
}const ins = JSON.parse($('Record candidates').item.json.inserted || '[]');
let ui = {};
try { ui = JSON.parse($('Collect chat').first().json.ui || '{}'); } catch (e) { ui = {}; }
const { t, fill } = uiRender(ui);
const out = [];
for (const c of ins) {
  let line;
  if (c.target_kind === 'fact') {
    line = fill(t(c.kind === 'update' ? 'core.learn.fact_update' : 'core.learn.fact_new'),
      { context: c.context_name, person: c.person_slug, field: c.field, value: c.proposed_value });
  } else {
    line = fill(t('core.learn.note'), { context: c.context_name, value: c.proposed_value });
  }
  if (c.rationale) { line = line + '\n(' + c.rationale + ')'; }
  out.push({ json: { id: c.id, line: line, btn_save: t('core.learn.btn_save'), btn_discard: t('core.learn.btn_discard') } });
}
return out;
